fn is_non_prime(n: u64) -> bool {
    // Given n >= 2 per problem statement

    // Handle n = 2 explicitly, which is prime
    if n == 2 {
        return false;
    }

    // To check if n has any divisor k with 2 <= k < n,
    // test divisors up to sqrt(n)
    let limit = (n as f64).sqrt() as u64;

    for k in 2..=limit {
        if n % k == 0 {
            return true; // Non-trivial divisor found
        }
    }

    false // No divisor found, n is prime
}